Definition sqd_lfacts (P : sqp) (OEND LLO LEND BND OP LP bc ptr sLL sOF sML : Z) : Prop :=
  w_DST P <= OP <= OEND /\ LLO <= LP <= LEND /\
  0 <= sLL < 2^(st_log (w_tLL P)) /\ 0 <= sOF < 2^(st_log (w_tOF P)) /\ 0 <= sML < 2^(st_log (w_tML P)) /\
  0 <= bc <= BND /\ bit_ok (w_SEQ P) (zlen (w_sq P)) bc ptr.

