Definition sqd_next (P : sqp) (nLL bLL nOF bOF nML bML : Z) : Prop :=
  0 <= bLL <= 9 /\ 0 <= nLL /\ nLL + 2^bLL <= 2^(st_log (w_tLL P)) /\
  0 <= bOF <= 9 /\ 0 <= nOF /\ nOF + 2^bOF <= 2^(st_log (w_tOF P)) /\
  0 <= bML <= 9 /\ 0 <= nML /\ nML + 2^bML <= 2^(st_log (w_tML P)).

