Definition sqd_fast (OEND LEND OP LP llv mlv : Z) : Prop :=
  0 <= llv < 2^18 /\ 0 <= mlv < 2^18 /\ LP + llv <= LEND /\ OP + llv + mlv <= OEND - 32.

