Definition sqd_mfast (P : sqp) (OEND OP ole mlv sl : Z) : Prop :=
  w_DST P <= OP <= ole /\ 0 <= mlv < 2^18 /\ ole + mlv <= OEND - 32 /\ sl = ole - OP + mlv.

